(* [comment removed for export] *)
Lemma mid_sv fxi Ri Mi mdi cri si smi eni ki ei Y fxj Rj Mj :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y -> mem_grows Mi Mj ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 64 <= i < sp - 64 + 16) -> Mj (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
  hi_heap HI (PEC.owned si eni ki ++ LBX) cri Mj (m_vmmaps mdi) ->
  getr Rj (PMK.reg 2) = getr Ri (PMK.reg 2) -> getr Rj (PMK.reg 8) = getr Ri (PMK.reg 8) -> getr Rj (PMK.reg 9) = getr Ri (PMK.reg 9) ->
  getr Rj (PMK.reg 18) = getr Ri (PMK.reg 18) -> (forall j, In j CSK -> getr Rj (PMK.reg j) = getr Ri (PMK.reg j)) ->
