Lemma call_valid (pp n ra : Z) (l : list Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr Ri (PMK.reg 10) = Z_to_bv 64 pp -> getr Ri (PMK.reg 11) = Z_to_bv 64 n ->
  0 <= n < 2 ^ 26 -> 0 <= pp -> (n = 0 \/ 0 < pp) -> pp + n <= 2 ^ 47 -> L5.defined Mi pp n -> (sp - 64 <= pp \/ pp + n <= sp - 64 - 12288) ->
  L5.bytes_at RSEGS Mi pp l -> Z.of_nat (length l) = n -> Forall (fun b => 0 <= b < 256) l ->
